/**
 * Theme completeness (issue #3826).
 *
 * `required-tokens.generated.json` lists every `--smrt-*` theme token that a
 * component consumes (generated by `scripts/generate-smrt-required-tokens.mjs`).
 * Every built-in preset, in light and dark mode, and a `createTheme()` output
 * must define each of them. A component that starts consuming a token a theme
 * lacks fails here instead of silently rendering a fallback colour.
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { createTheme } from '../create-theme.js';
import { generateThemeCSS } from '../css-generator.js';
import { availablePresets, getTheme } from '../registry.js';
import type { Theme } from '../types.js';

interface RequiredTokenList {
  required: string[];
  optional: string[];
}

// Resolved from process.cwd() (NOT import.meta.url): the smrt-vitest plugin
// does not give import.meta.url a file scheme. Same convention as token-aliases.
const packageRoot = process.cwd().endsWith('packages/smrt-ui')
  ? process.cwd()
  : join(process.cwd(), 'packages/smrt-ui');

const LIST: RequiredTokenList = JSON.parse(
  readFileSync(
    join(packageRoot, 'src/themes/required-tokens.generated.json'),
    'utf8',
  ),
);

/** `--smrt-*` names a generated theme stylesheet declares. */
function declaredTokens(css: string): Set<string> {
  const names = new Set<string>();
  for (const match of css.matchAll(/^\s*(--smrt-[a-z0-9_-]+)\s*:/gim)) {
    names.add(match[1]);
  }
  return names;
}

function missingFrom(theme: Theme, isDark: boolean): string[] {
  const defined = declaredTokens(generateThemeCSS(theme, isDark));
  return LIST.required.filter((token) => !defined.has(token));
}

describe('required theme tokens (generated list)', () => {
  it('is a non-empty, sorted, duplicate-free list of --smrt-* names', () => {
    expect(LIST.required.length).toBeGreaterThan(0);
    expect(LIST.required).toEqual([...LIST.required].sort());
    expect(new Set(LIST.required).size).toBe(LIST.required.length);
    for (const token of LIST.required)
      expect(token).toMatch(/^--smrt-[a-z0-9_-]+$/);
  });

  it('keeps override hooks out of the required set', () => {
    for (const token of LIST.optional)
      expect(LIST.required).not.toContain(token);
  });

  for (const preset of availablePresets) {
    for (const mode of ['light', 'dark'] as const) {
      it(`preset "${preset}" defines every required token (${mode})`, () => {
        expect(missingFrom(getTheme(preset), mode === 'dark')).toEqual([]);
      });
    }
  }

  for (const mode of ['light', 'dark'] as const) {
    it(`a createTheme() output defines every required token (${mode})`, () => {
      const theme = createTheme({
        id: 'required-tokens-probe',
        name: 'Required tokens probe',
        light: { primary: '#336699', background: '#ffffff' },
      });
      expect(missingFrom(theme, mode === 'dark')).toEqual([]);
    });
  }

  it('a createTheme() output extending a preset defines every required token', () => {
    const theme = createTheme({
      id: 'required-tokens-probe-extended',
      name: 'Required tokens probe (extended)',
      extend: 'glass',
      light: { primary: '#7a3e00', background: '#fffaf0' },
    });
    expect(missingFrom(theme, false)).toEqual([]);
    expect(missingFrom(theme, true)).toEqual([]);
  });
});
